#!/usr/bin/env python3
"""Regenerate PRODUCTION_TRACKER.md from STYLE_INVENTORY.json + each style folder's status.json (single source of truth for status)."""
import json, os
B = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
inv = json.load(open(f'{B}/STYLE_INVENTORY.json'))
ICON = {'done': '✅', 'qa': '🔎', 'wip': '🟡', 'blocked': '⛔', 'queued': '⏳'}
L = ['# LEMO_STYLE_BENCHMARK — production tracker', '', f"Library commit `{inv['library_commit']}` · {inv['count']} styles. Status per style lives in `styles/<id>_<slug>/status.json`;",
     'this file is regenerated by `tools/build_tracker.py`.', '', '## Resume point', '']
rp = open(f'{B}/RESUME.md').read().strip() if os.path.exists(f'{B}/RESUME.md') else '(see RESUME.md)'
L += [rp, '', '## Styles', '', '| id | style | category | series | status | notes |', '|---|---|---|---|---|---|']
counts = {}
for r in inv['styles']:
    st = {'status': 'blocked' if r['needs_image_generator'] else 'queued', 'note': 'needs an image generator — none available here' if r['needs_image_generator'] else ''}
    p = f"{B}/{r['folder']}/status.json"
    if os.path.exists(p): st.update(json.load(open(p)))
    counts[st['status']] = counts.get(st['status'], 0) + 1
    adapt = ' · narrative adaptation' if r['narrative_adaptation'] else ''
    L.append(f"| {r['bench_id']} | {r['name']} (`{r['slug']}`) | {r['category']} | {r['series']} | {ICON[st['status']]} {st['status']} | {st.get('note', '')}{adapt} |")
L[6:6] = ['', '**Totals:** ' + ' · '.join(f'{ICON[k]} {k}: {v}' for k, v in sorted(counts.items())), '']
open(f'{B}/PRODUCTION_TRACKER.md', 'w').write('\n'.join(L) + '\n'); print(counts)
